'use client';

import Link from 'next/link';
import { useParams } from 'next/navigation';
import { useEffect, useState } from 'react';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';

type RequestStatus = 'Pending' | 'Approved' | 'Rejected' | 'Cancelled' | 'Released';

interface ApiEnvelope<T> {
  success: boolean;
  message: string;
  data: T;
}

interface RequestDetail {
  id: number;
  section?: {
    section_name?: string;
    year_level?: number;
    expected_students?: number;
    course?: { course_code?: string; course_title?: string; units?: number };
  };
  room?: {
    room_number?: string;
    building?: string;
    capacity?: number;
    type?: { name?: string };
  };
  day_of_week: string;
  time_start: string;
  time_end: string;
  status: RequestStatus;
  admin_remarks: string | null;
  submitted_at: string;
  reviewed_at: string | null;
}

function fmt12(t: string) {
  const [h, m] = t.split(':').map(Number);
  return `${h % 12 || 12}:${String(m).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`;
}

function fmtDate(ts: string) {
  return new Date(ts).toLocaleDateString('en-PH', { year: 'numeric', month: 'short', day: 'numeric' });
}

export default function RequestDetailPage() {
  const params = useParams<{ id: string }>();
  const id = Number(params?.id);

  const [row, setRow] = useState<RequestDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [acting, setActing] = useState(false);
  const [error, setError] = useState('');

  async function load() {
    if (!id) return;
    setLoading(true);
    setError('');
    try {
      const res = await api.get<ApiEnvelope<RequestDetail>>(`/requests/${id}`);
      setRow(res.data);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to load request.');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, [id]);

  async function act(action: 'cancel' | 'release') {
    if (!row) return;
    setActing(true);
    setError('');
    try {
      await api.post<ApiEnvelope<null>>(`/requests/${row.id}/${action}`, { remarks: null });
      setRow((prev) => (prev ? { ...prev, status: action === 'cancel' ? 'Cancelled' : 'Released' } : prev));
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : `Failed to ${action} request.`);
    } finally {
      setActing(false);
    }
  }

  return (
    <AppShell role="instructor" userName="Instructor" pageTitle={`Request #${id}`}>
      <div className="max-w-2xl mx-auto">
        <div className="flex items-center gap-3 mb-5">
          <Link href="/requests" className="btn btn-ghost">Back</Link>
          <h1 className="text-[18px] font-semibold">Request #{id}</h1>
        </div>

        {error && <div className="card p-4 mb-4 text-sm" style={{ color: 'var(--color-error)' }}>{error}</div>}

        {loading ? (
          <div className="card p-6 text-sm" style={{ color: 'var(--color-text-muted)' }}>Loading request...</div>
        ) : !row ? (
          <div className="card p-6 text-sm" style={{ color: 'var(--color-text-muted)' }}>Request not found.</div>
        ) : (
          <div className="card card-body flex flex-col gap-4">
            <div className="flex items-center justify-between gap-3 flex-wrap">
              <div>
                <p className="text-[13px] font-semibold">{row.section?.course?.course_code ?? 'N/A'} · {row.section?.section_name ?? 'N/A'}</p>
                <p className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>Submitted {fmtDate(row.submitted_at)}</p>
              </div>
              <span className="text-[11px] px-2 py-0.5 rounded-full" style={{ background: 'var(--color-surface-2)', color: 'var(--color-text-secondary)' }}>
                {row.status}
              </span>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-[12.5px]">
              <div><strong>Course:</strong> {row.section?.course?.course_title ?? 'N/A'}</div>
              <div><strong>Section:</strong> {row.section?.section_name ?? 'N/A'}</div>
              <div><strong>Day:</strong> {row.day_of_week}</div>
              <div><strong>Time:</strong> {fmt12(row.time_start)} - {fmt12(row.time_end)}</div>
              <div><strong>Room:</strong> {row.room?.room_number ?? 'N/A'} · {row.room?.building ?? 'N/A'}</div>
              <div><strong>Capacity:</strong> {row.room?.capacity ?? 'N/A'}</div>
            </div>

            {row.admin_remarks && (
              <div className="rounded-lg p-3 text-sm" style={{ background: 'var(--color-error-light)', color: 'var(--color-error)' }}>
                {row.admin_remarks}
              </div>
            )}

            <div className="flex gap-3">
              {row.status === 'Pending' && (
                <button className="btn btn-ghost" disabled={acting} onClick={() => act('cancel')}>
                  {acting ? 'Cancelling...' : 'Cancel Request'}
                </button>
              )}
              {row.status === 'Approved' && (
                <button className="btn btn-ghost" disabled={acting} onClick={() => act('release')}>
                  {acting ? 'Releasing...' : 'Release Booking'}
                </button>
              )}
            </div>
          </div>
        )}
      </div>
    </AppShell>
  );
}
